import{z as s,x as i,o,c,q as e,j as B,D as t,d as r,s as l,S as n}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"Llama 4 Scout","description":"","frontmatter":{"title":"Llama 4 Scout","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/llama-4-scout.md","filePath":"llm/llama-4-scout.md","lastUpdated":1791063341000}'),A={name:"llm/llama-4-scout.md"};function m(u,a,h,M,d,p){const E=i("Mermaid");return o(),c("div",null,[a[2]||(a[2]=e('<h1 id="llama-4-scout" tabindex="-1">Llama 4 Scout <a class="header-anchor" href="#llama-4-scout" aria-label="Permalink to &quot;Llama 4 Scout&quot;">​</a></h1><div class="epigraph"><p>Llama 4 Scout 是 170 亿激活、16 个专家的原生多模态 MoE：BF16 发布，INT4 可进单张 H100；预训练与后训练看见 256K，输入上下文被写成千万量级。</p><footer>—— Meta，The Llama 4 herd（2025-04-05）；官方模型卡 Llama 4 Scout 17Bx16E</footer></div><p>Llama 4 族里，<strong>Scout</strong> 是为「单卡可放」切的那一档：约 <strong>17B 激活、16 专家、总参约 109B</strong>。同日的 <a href="/llm/llama-4-maverick">Maverick</a> 激活量接近、专家库大四倍；教师 Behemoth 当时不开放。族级叙事见 <a href="/llm/llama-4">Llama 4</a> 与 <a href="/llm/llama4-report">技术报告笔记</a>。本篇按 2025-04-05 博客与 Hugging Face / <code>llama-models</code> 卡片写 Scout，不编未公布的层宽。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Maverick 的 400B 总量即使激活只有 17B，也要一整台 H100 主机。Scout 要回答：在<strong>同一量级的每 token FLOPs</strong>上，把专家数降到 16、总参降到约 109B，质量能否仍明显高于 Llama 3.3 70B 稠密，并顺带把图文早融合和超长输入做进开权默认。INT4 单卡是部署约束，不是训练精度。</p><p>另一条轴是上下文。卡片把 Scout 的 context length 写成 <strong>10M</strong>、token count 约 <strong>40T</strong>、知识截止 2024 年 8 月。<span class="marginnote">常见误区：卡片写 context length 10M，不等于服务时要按 10M 建 KV——真那样采购显存成本会不可行。10M 是长度泛化的外推主张，实用长度取决于 KV 分页、稀疏化与检索。</span>博客把<strong>训过的窗口</strong>写成 256K，10M 是长度泛化主张，证据是针检索与长代码 NLL。工程必须把两数分开，否则会按 10M 全量 KV 去采购 HBM。</p><h3 id="博客与卡片对得上的数字" tabindex="-1">博客与卡片对得上的数字 <a class="header-anchor" href="#博客与卡片对得上的数字" aria-label="Permalink to &quot;博客与卡片对得上的数字&quot;">​</a></h3><p>博客：首次 MoE；Scout 17B 激活 / 16 专家 / ~109B；原生多模态 early fusion；视觉编码器基于 MetaCLIP，对着冻结 Llama 骨干适配；iRoPE；预训练混合超过 30T 的族级叙述。卡片：输入为多语文本与图像，输出为多语文本与代码；支持语种列出阿、英、法、德、印地、印尼、意、葡、西、他加禄、泰、越；预训练实际覆盖约 200 种语言。训练算力：Scout <strong>500 万 H100-小时</strong>（族合计 738 万）。量化：以 BF16 发布，提供即时 INT4 以进单卡，评测在 BF16 上做。</p><p><span class="marginnote">族级「混合超过 30T」与卡片 Scout「~40T」不是同一口径。不要用 40T 去减 Maverick 的 22T 得到 Scout 的「多训量」，也不要把 30T 加到 40T 上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>MoE 层：16 个路由专家，激活量与 Maverick 对齐到约 17B，专家更少则并行更简单、专家利用率更高、组合更粗。博客未把 Scout 写成「共享专家 + \\(k=1\\)」那句 Maverick 专用描述；实现以发布配置为准，不要把 Maverick 的公式抄到 Scout 头上还假装来自同一段落。交替稠密 / MoE 是 Maverick 的明确句；Scout 是否每层都是 MoE，博客只给定性，本篇保持不确定。</p><p>超长：架构名 <strong>iRoPE</strong>——多数层 RoPE，交错插入无位置编码层，推理时对注意力做温度缩放。「i」同时指 interleaved 与 infinite 的志向。256K 是预训练/后训练见过的长度；10M 是外推点。<span class="marginnote">直觉类比：iRoPE 像一本交替排版的书——大部分页印着局部坐标（RoPE 层，管「离这里几个词」），每隔几页插一张无坐标的章节分隔页（NoPE 层，只管全局先后）。千万下标来了，坐标页不会全部卷绕，全局顺序由分隔页兜底。</span>后训练族级管道：轻 SFT（丢掉过易样本）→ 多模态在线 RL → 轻 DPO；Scout 与 Maverick 都从 Behemoth <strong>共蒸馏</strong>。教师未开放，学生里的 STEM 行为有一块无法从开源图还原。</p>',12)),(o(),B(n,null,{default:t(()=>[l(E,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20MIX%5B%22%E5%85%AC%E5%BC%80%20%2B%20%E8%AE%B8%E5%8F%AF%20%2B%20Meta%20%E4%BA%A7%E5%93%81%E6%95%B0%E6%8D%AE%20~40T%20%E5%8F%A3%E5%BE%84%22%5D%20--%3E%20PT%5B%22%E9%A2%84%E8%AE%AD%E7%BB%83%20%2F%20%E6%97%A9%E8%9E%8D%E5%90%88%E5%9B%BE%E6%96%87%22%5D%0A%20%20BEH%5B%22Behemoth%20%E6%95%99%E5%B8%88%22%5D%20--%3E%20DIST%5B%22%E5%85%B1%E8%92%B8%E9%A6%8F%22%5D%0A%20%20DIST%20--%3E%20PT%0A%20%20PT%20--%3E%20MID%5B%22%E4%B8%AD%E8%AE%AD%EF%BC%9A%E9%95%BF%E4%B8%8A%E4%B8%8B%E6%96%87%E4%B8%93%E9%A1%B9%22%5D%0A%20%20MID%20--%3E%20SFT%5B%22%E8%BD%BB%20SFT%EF%BC%8C%E6%BB%A4%E6%8E%89%E8%BF%87%E6%98%93%22%5D%0A%20%20SFT%20--%3E%20RL%5B%22%E5%A4%9A%E6%A8%A1%E6%80%81%E5%9C%A8%E7%BA%BF%20RL%22%5D%0A%20%20RL%20--%3E%20DPO%5B%22%E8%BD%BB%20DPO%22%5D%0A%20%20DPO%20--%3E%20OUT%5B%22Scout%2017B%C3%9716E%20%2F%20109B%22%5D%0A%20%20OUT%20--%3E%20Q%5B%22INT4%20%E2%86%92%20%E5%8D%95%20H100%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e('<h3 id="卡片上的-base-instruct-表" tabindex="-1">卡片上的 Base / Instruct 表 <a class="header-anchor" href="#卡片上的-base-instruct-表" aria-label="Permalink to &quot;卡片上的 Base / Instruct 表&quot;">​</a></h3><p>预训练对照（卡片）：MMLU 5-shot Scout 79.6 vs Llama 3.1 70B 79.3、405B 85.2；MMLU-Pro 58.2 vs 70B 53.8；MATH 50.3 vs 70B 41.6；MBPP 67.8；ChartQA 83.4、DocVQA 89.4（3.x 无图）。Instruct：MMMU 69.4、MMMU Pro 52.2、MathVista 70.7、LiveCodeBench 32.8、MMLU Pro 74.3、GPQA Diamond <strong>57.2</strong>、MGSM 90.6。长上下文 MTOB 半本 / 全本 chrF 给出 10M 叙事下的翻译探针，不是综合 10M 任务集。图像理解官方测试到 <strong>5 张输入图</strong>；更多图属开发者自测区。预训练最多约 48 张图、后训练测到 8 张是族级博文句。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>16 专家的机制承诺是：容量来自专家库而不是激活。路由若塌成总用两三个专家，109B 只是占盘，行为退回「略宽的 17B」。少专家使 top-\\(k\\) 的负载更易均衡，也使细技能组合少——数学与代码上卡片显示 Scout 明显弱于 Maverick（Instruct GPQA 57.2 vs 69.8，LiveCodeBench 32.8 vs 43.4），这与「同样 17B 激活」不矛盾：库更大的 MoE 在蒸馏加持下装了更多专项。</p><p>iRoPE 把局部相对几何和超长顺序拆层。RoPE 层继续提供邻域相位；NoPE 层避免所有层在千万下标上卷绕。温度缩放改 softmax 锋利度，不改相对位置。10M 没有论文级消融，不能归因成「只加了 NoPE」。早融合让视觉 token 进同一自注意力；Scout 的图文分数（ChartQA / DocVQA）说明这条在 16 专家档上也成立，只是 MMMU 仍低于 Maverick。</p>',5)),(o(),B(n,null,{default:t(()=>[l(E,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22iRoPE%20%E4%BA%A4%E6%9B%BF%E5%B1%82%22%5D%20--%3E%20R%5B%22RoPE%20%E5%B1%82%EF%BC%9A%E5%B1%80%E9%83%A8%E7%9B%B8%E5%AF%B9%E7%9B%B8%E4%BD%8D%22%5D%0A%20%20L%20--%3E%20N%5B%22NoPE%20%E5%B1%82%EF%BC%9A%E6%97%A0%E4%BD%8D%E7%BD%AE%E7%BC%96%E7%A0%81%22%5D%0A%20%20R%20--%3E%20R1%5B%22%E7%AE%A1%E9%82%BB%E5%9F%9F%E4%B8%8E%E6%AE%B5%E5%86%85%E7%9A%84%E7%9B%B8%E5%AF%B9%E5%87%A0%E4%BD%95%22%5D%0A%20%20N%20--%3E%20N1%5B%22%E9%81%BF%E5%85%8D%E6%89%80%E6%9C%89%E5%B1%82%E5%9C%A8%E5%8D%83%E4%B8%87%E4%B8%8B%E6%A0%87%E4%B8%8A%E5%8D%B7%E7%BB%95%22%5D%0A%20%20R1%20--%3E%20S%5B%22%E6%8E%A8%E7%90%86%E6%97%B6%E5%86%8D%E5%AF%B9%E6%B3%A8%E6%84%8F%E5%8A%9B%E5%81%9A%E6%B8%A9%E5%BA%A6%E7%BC%A9%E6%94%BE%22%5D%0A%20%20N1%20--%3E%20S%0A%20%20S%20--%3E%20O%5B%22256K%20%E8%AE%AD%E8%BF%87%E7%AA%97%20%2B%20%E5%A4%96%E6%8E%A8%E5%88%B0%E6%9B%B4%E9%95%BF%EF%BC%8810M%20%E4%B8%BB%E5%BC%A0%EF%BC%89%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e('<p><span class="marginnote">训练数据含 Meta 产品与公开分享的 Instagram / Facebook 帖及 Meta AI 交互——与 Llama 3 卡片「不含 Meta 用户数据」不是同一句。许可是 Llama 4 Community License，月活超 7 亿要另谈商务。再分发须保留 Notice 与 Built with Llama。</span></p><h3 id="蒸馏与「单卡-17b」的错觉" tabindex="-1">蒸馏与「单卡 17B」的错觉 <a class="header-anchor" href="#蒸馏与「单卡-17b」的错觉" aria-label="Permalink to &quot;蒸馏与「单卡 17B」的错觉&quot;">​</a></h3><p>质量有一块来自仍在训练的 Behemoth，不是 16 专家自己从 40T 里长出全部 STEM。按稠密 17B 去对标会低估存储（专家权仍要在内存或 PCIe 上），也会高估「小模型从零练到 GPQA 57」的可复现性。INT4 是推理技巧；训练与官方表是 BF16。单卡能装不等于 10M 能跑：KV 才是长度的主成本，实用长度取决于分页、稀疏或检索。中训被博客写成用专门长上下文数据再抬一截能力，同时解锁超长输入主张——与 <a href="/llm/olmo2-midtrain-recipe">OLMo 2 式数学补丁</a> 不同，这里买的是窗口，不是 GSM8K。没有公开中训混合表，不能把 Dolmino 配比套过来。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>10M 是宣传外推，256K 是训过的窗。针测与 NLL 不能代替多跳长文档。专家并行在 16 专家上比 128 轻，但路由实现仍要正确，不能当稠密 109B 用。多语：预训练 200 语种，官方支持列表 12 种，其余要自己测安全与质量。<span class="marginnote">数字实例：预训练见过约 200 种语言 ≠ 支持约 200 种。官方「达到门槛」的列表只有 12 种；其余近 190 种属于「切得动、生成得出」，安全与质量必须自己回归。</span>视频被写成帧静图。Behemoth 的 MATH-500 / GPQA 对照是教师自报，不能写进 Scout 的成绩单。</p><p>硬件卡写训练在 Meta 自建 GPU 集群与生产基础设施上完成，微调、量化、标注、评测同样走生产栈。温室气体：Scout 训练的位置基准排放约 1,354 吨 CO2eq，市场基准因 100% 可再生匹配记 0。这些数字是卡片披露，不是服务质量承诺。</p><p>不要给 Scout 编一层层宽。不要把 Maverick 的 1M 写成 Scout 的窗口。不要假设许可与 3.x 逐字相同。社区对发布评测有过争议时，系统回归以自有任务为准。卡片还给出一份可改的系统提示模板，强调少说教、可闲聊、知识截止 2024-08、按用户语言回答；这是 Instruct 语气工作，不能当成 Base 检查点的默认行为。预训练权重与 Instruct 权重要分开部署：前者给续训，后者给助手。图像 caption、视觉问答、合成数据与蒸馏被写成许可内的用途；用输出再去训练公开模型时，须遵守「Llama」冠名条款。</p><p><span class="marginnote">出处：Meta，<em>The Llama 4 herd</em>，2025-04-05；<code>meta-llama/Llama-4-Scout-17B-16E</code> 模型卡。对照见 <a href="/llm/llama-4-maverick">Llama 4 Maverick</a>。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Scout：17B 激活 / 16 专家 / 109B 总量，原生多模态 MoE，INT4 单 H100，约 500 万 GPU 小时。</li><li>卡片上下文 10M、约 40T token、截止 2024-08；博客训练窗 256K + iRoPE 外推。</li><li>Instruct GPQA Diamond 57.2；图文 ChartQA / DocVQA 可用；编码与 STEM 低于 Maverick。</li><li>共蒸馏自未开放的 Behemoth；数据含 Meta 产品公开交互。</li><li>出处：2025-04-05 博客与官方模型卡。</li></ul>',10))])}const S=s(A,[["render",m]]);export{D as __pageData,S as default};
